const express = require('express');
const app = express();

// Get port from environment variable or default to 3000
const PORT = process.env.PORT || 3000;

// Middleware to parse JSON bodies
app.use(express.json());

// Request logging middleware for production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    console.log(`${new Date().toISOString()} - ${req.method} ${req.path}`);
    next();
  });
}

// Basic error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ 
    error: 'Internal server error',
    message: process.env.NODE_ENV === 'production' ? 'An unexpected error occurred' : err.message
  });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Get all users
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Create new user with input validation
app.post('/users', (req, res) => {
  try {
    const { name } = req.body;

    // Check if name field exists
    if (name === undefined || name === null) {
      return res.status(400).json({ 
        error: 'Missing required field: name' 
      });
    }

    // Check if name is a string
    if (typeof name !== 'string') {
      return res.status(400).json({ 
        error: 'Invalid field type: name must be a string' 
      });
    }

    // Check if name is not empty
    const trimmedName = name.trim();
    if (trimmedName.length === 0) {
      return res.status(400).json({ 
        error: 'Invalid field value: name cannot be empty' 
      });
    }

    // Limit name length for security
    if (trimmedName.length > 100) {
      return res.status(400).json({ 
        error: 'Invalid field value: name must be less than 100 characters' 
      });
    }

    // If validation passes, process the request
    const newUser = {
      id: Date.now(),
      name: trimmedName,
      email: `${trimmedName.toLowerCase().replace(/\s+/g, '.')}@example.com`,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });

  } catch (error) {
    console.error('Error in POST /users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to create user'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.path,
    method: req.method
  });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

