{
  "name": "express-api",
  "version": "1.0.0",
  "description": "Simple Express API with input validation",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "jest"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "nodemon": "^3.0.1",
    "supertest": "^6.3.3"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}

const request = require('supertest');
const app = require('../app');

describe('POST /users input validation', () => {
  test('should reject missing name field with 400', async () => {
    const response = await request(app)
      .post('/users')
      .send({});

    expect(response.status).toBe(400);
    expect(response.body.error).toMatch(/Missing required field/);
  });

  test('should reject non-string name with 400', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    expect(response.status).toBe(400);
    expect(response.body.error).toMatch(/Invalid data type/);
  });

  test('should reject empty name with 400', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' });

    expect(response.status).toBe(400);
    expect(response.body.error).toMatch(/cannot be empty/);
  });

  test('should accept valid name with 201', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'Charlie' });

    expect(response.status).toBe(201);
    expect(response.body.message).toBe('User created successfully');
    expect(response.body.user.name).toBe('Charlie');
  });
});

