async function testValidation() {
  console.log('Testing POST /users validation...\n');

  const testCases = [
    // Test 1: Missing name field
    {
      name: 'Missing name field',
      data: { email: 'test@example.com' },
      expectedError: 'Missing required field: name'
    },
    // Test 2: Non-string name (number)
    {
      name: 'Non-string name (number)',
      data: { name: 123 },
      expectedError: 'Field "name" must be a string'
    },
    // Test 3: Non-string name (object)
    {
      name: 'Non-string name (object)',
      data: { name: { first: 'John', last: 'Doe' } },
      expectedError: 'Field "name" must be a string'
    },
    // Test 4: Empty string name
    {
      name: 'Empty string name',
      data: { name: '' },
      expectedError: 'Field "name" cannot be empty or whitespace'
    },
    // Test 5: Whitespace-only name
    {
      name: 'Whitespace-only name',
      data: { name: '   ' },
      expectedError: 'Field "name" cannot be empty or whitespace'
    },
    // Test 6: Valid name (should succeed)
    {
      name: 'Valid name',
      data: { name: 'John Doe' },
      shouldSucceed: true
    }
  ];

  for (const testCase of testCases) {
    console.log(`Test: ${testCase.name}`);
    console.log(`Request data:`, testCase.data);

    try {
      const response = await axios.post(`${BASE_URL}/users`, testCase.data);

      if (testCase.shouldSucceed) {
        console.log('✓ SUCCESS: Request passed validation');
        console.log(`Response:`, response.data);
      } else {
        console.log('✗ FAIL: Expected validation error but request succeeded');
      }
    } catch (error) {
      if (error.response) {
        // Server responded with error status
        if (!testCase.shouldSucceed && error.response.status === 400) {
          const errorMessage = error.response.data.error;
          if (errorMessage === testCase.expectedError) {
            console.log(`✓ PASS: Got expected error: "${errorMessage}"`);
          } else {
            console.log(`✗ FAIL: Got error: "${errorMessage}", expected: "${testCase.expectedError}"`);
          }
        } else if (testCase.shouldSucceed) {
          console.log('✗ FAIL: Expected success but got error:', error.response.data);
        } else {
          console.log('✗ FAIL: Unexpected error:', error.response.data);
        }
      } else {
        console.log('✗ FAIL: Network or other error:', error.message);
      }
    }
    console.log('---\n');
  }
}

