const request = require('supertest');
const app = require('../app');

describe('POST /users validation', () => {
  it('should create a user with valid name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John Doe' })
      .expect(201);

    expect(response.body.message).toBe('User created successfully');
    expect(response.body.user.name).toBe('John Doe');
    expect(typeof response.body.user.id).toBe('number');
  });

  it('should reject request with missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({})
      .expect(400);

    expect(response.body.error).toBe('Missing required field: name');
  });

  it('should reject request with null name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: null })
      .expect(400);

    expect(response.body.error).toBe('Missing required field: name');
  });

  it('should reject request with non-string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 })
      .expect(400);

    expect(response.body.error).toBe('Field "name" must be a string');
  });

  it('should reject request with empty string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' })
      .expect(400);

    expect(response.body.error).toBe('Field "name" cannot be empty');
  });

  it('should reject request with whitespace-only name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' })
      .expect(400);

    expect(response.body.error).toBe('Field "name" cannot be empty');
  });

  it('should trim whitespace from valid names', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '  Jane Smith  ' })
      .expect(201);

    expect(response.body.user.name).toBe('Jane Smith');
  });
});

describe('GET endpoints', () => {
  it('should return health status', async () => {
    const response = await request(app)
      .get('/health')
      .expect(200);

    expect(response.body.status).toBe('ok');
    expect(response.body.timestamp).toBeDefined();
  });

  it('should return users list', async () => {
    const response = await request(app)
      .get('/users')
      .expect(200);

    expect(Array.isArray(response.body)).toBe(true);
    expect(response.body.length).toBe(2);
  });
});

module.exports = {
  testEnvironment: 'node',
  testMatch: [
    '**/test/**/*.test.js'
  ],
  collectCoverage: true,
  coverageDirectory: 'coverage',
  coverageReporters: ['text', 'lcov'],
  collectCoverageFrom: [
    'app.js'
  ]
};

