// Test script to verify the input validation in app.js

const http = require('http');

const testCases = [
  {
    name: 'Missing name field',
    body: { email: 'test@example.com' },
    expectedStatus: 400,
    expectedMessage: 'The "name" field is required'
  },
  {
    name: 'Name field is null',
    body: { name: null },
    expectedStatus: 400,
    expectedMessage: 'The "name" field is required'
  },
  {
    name: 'Name field is a number',
    body: { name: 123 },
    expectedStatus: 400,
    expectedMessage: 'The "name" field must be a string'
  },
  {
    name: 'Name field is an object',
    body: { name: { first: 'John', last: 'Doe' } },
    expectedStatus: 400,
    expectedMessage: 'The "name" field must be a string'
  },
  {
    name: 'Name field is empty string',
    body: { name: '' },
    expectedStatus: 400,
    expectedMessage: 'The "name" field cannot be empty'
  },
  {
    name: 'Name field is whitespace only',
    body: { name: '   ' },
    expectedStatus: 400,
    expectedMessage: 'The "name" field cannot be empty'
  },
  {
    name: 'Valid name (should succeed)',
    body: { name: 'John Doe' },
    expectedStatus: 201,
    expectedMessage: 'User created successfully'
  },
  {
    name: 'Valid name with trailing spaces (should be trimmed)',
    body: { name: '  Jane Doe  ' },
    expectedStatus: 201,
    expectedMessage: 'User created successfully'
  }
];

function runTest(testCase) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(testCase.body);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/users',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const response = data ? JSON.parse(data) : {};

        if (res.statusCode === testCase.expectedStatus) {
          if (testCase.expectedStatus === 400) {
            if (response.message === testCase.expectedMessage) {
              resolve({ 
                test: testCase.name, 
                status: 'PASS', 
                message: `Got expected error: ${testCase.expectedMessage}` 
              });
            } else {
              resolve({ 
                test: testCase.name, 
                status: 'FAIL', 
                message: `Expected error message "${testCase.expectedMessage}" but got "${response.message}"` 
              });
            }
          } else {
            if (response.message === testCase.expectedMessage) {
              resolve({ 
                test: testCase.name, 
                status: 'PASS', 
                message: `Success: ${testCase.expectedMessage}` 
              });
            } else {
              resolve({ 
                test: testCase.name, 
                status: 'FAIL', 
                message: `Expected success message "${testCase.expectedMessage}" but got "${response.message}"` 
              });
            }
          }
        } else {
          resolve({ 
            test: testCase.name, 
            status: 'FAIL', 
            message: `Expected status ${testCase.expectedStatus} but got ${res.statusCode}` 
          });
        }
      });
    });

    req.on('error', (error) => {
      resolve({ 
        test: testCase.name, 
        status: 'ERROR', 
        message: `Request failed: ${error.message}` 
      });
    });

    req.write(postData);
    req.end();
  });
}

async function runAllTests() {
  console.log('Starting validation tests...\n');

  for (const testCase of testCases) {
    try {
      const result = await runTest(testCase);
      console.log(`${result.status === 'PASS' ? '✓' : '✗'} ${result.test}`);
      if (result.status !== 'PASS') {
        console.log(`  ${result.message}`);
      }
    } catch (error) {
      console.log(`✗ ${testCase.name}`);
      console.log(`  Error: ${error.message}`);
    }
    await new Promise(resolve => setTimeout(resolve, 100)); // Small delay between tests
  }

  console.log('\nTests completed.');
}

// Run tests
runAllTests();

