// Simplified example showing the validation logic added to app.js
// This demonstrates the input validation without running the full server

function validateUserRequest(body) {
  const { name } = body;

  // Validate the name field - this is the exact validation logic from app.js
  if (name === undefined || name === null) {
    return {
      valid: false,
      status: 400,
      error: {
        error: 'Bad Request',
        message: 'The "name" field is required'
      }
    };
  }

  if (typeof name !== 'string') {
    return {
      valid: false,
      status: 400,
      error: {
        error: 'Bad Request',
        message: 'The "name" field must be a string'
      }
    };
  }

  if (name.trim() === '') {
    return {
      valid: false,
      status: 400,
      error: {
        error: 'Bad Request',
        message: 'The "name" field cannot be empty'
      }
    };
  }

  return {
    valid: true,
    status: 201,
    success: {
      message: 'User created successfully',
      data: { name: name.trim() }
    }
  };
}

// Test the validation logic
const testCases = [
  { body: {}, expected: 'The "name" field is required' },
  { body: { name: null }, expected: 'The "name" field is required' },
  { body: { name: 123 }, expected: 'The "name" field must be a string' },
  { body: { name: {} }, expected: 'The "name" field must be a string' },
  { body: { name: '' }, expected: 'The "name" field cannot be empty' },
  { body: { name: '   ' }, expected: 'The "name" field cannot be empty' },
  { body: { name: 'John' }, expected: 'User created successfully' },
  { body: { name: '  Jane  ' }, expected: 'User created successfully' }
];

console.log('Testing Input Validation Logic\n');
console.log('='.repeat(50));

testCases.forEach((testCase, index) => {
  const result = validateUserRequest(testCase.body);

  if (result.valid) {
    console.log(`Test ${index + 1}: PASS`);
    console.log(`  Input: ${JSON.stringify(testCase.body)}`);
    console.log(`  Expected: "${testCase.expected}"`);
    console.log(`  Got: "${result.success.message}"`);
    console.log(`  Result: Status ${result.status}, Name: "${result.success.data.name}"`);
  } else {
    console.log(`Test ${index + 1}: ${result.error.message.includes(testCase.expected) ? 'PASS' : 'FAIL'}`);
    console.log(`  Input: ${JSON.stringify(testCase.body)}`);
    console.log(`  Expected: "${testCase.expected}"`);
    console.log(`  Got: "${result.error.message}"`);
    console.log(`  Result: Status ${result.status}, Error: ${result.error.message}`);
  }
  console.log('');
});

console.log('='.repeat(50));
console.log('\nSummary of changes made to app.js:');
console.log('1. Added express.json() middleware to parse JSON request bodies');
console.log('2. Added POST /users endpoint with comprehensive input validation');
console.log('3. Validation checks:');
console.log('   - name field must exist and not be null');
console.log('   - name field must be a string');
console.log('   - name field cannot be empty or whitespace-only');
console.log('4. Returns 400 status with clear error messages for invalid requests');
console.log('5. Returns 201 status with success message for valid requests');

// Quick test to verify app.js can be loaded and has the POST handler
console.log('Checking app.js modifications...\n');

try {
  // Read the app.js file
  const fs = require('fs');
  const appContent = fs.readFileSync('app.js', 'utf8');

  // Check for key components
  const checks = [
    { name: 'express.json() middleware', regex: /app\.use\(express\.json\(\)\)/, required: true },
    { name: 'POST /users endpoint', regex: /app\.post\s*\(\s*['"]\/users['"]/, required: true },
    { name: 'name field validation - missing/null check', regex: /name\s*===\s*undefined\s*\|\|\s*name\s*===\s*null/, required: true },
    { name: 'name field validation - string type check', regex: /typeof\s*name\s*!==\s*['"]string['"]/, required: true },
    { name: 'name field validation - empty string check', regex: /name\.trim\(\)\s*===\s*['"]{2}/, required: true },
    { name: '400 status return for validation failures', regex: /res\.status\(400\)/, required: true },
    { name: 'Clear error messages', regex: /message:\s*['"]The "name" field/, required: true },
    { name: '201 status for successful requests', regex: /res\.status\(201\)/, required: true }
  ];

  let passed = 0;
  let failed = 0;

  checks.forEach(check => {
