const request = require('supertest');
const app = require('../app');

describe('POST /users validation tests', () => {
  test('should reject request with missing name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({});

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Missing required field: name');
  });

  test('should reject request with null name field', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: null });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Missing required field: name');
  });

  test('should reject request with non-string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 123 });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Invalid data type: name must be a string');
  });

  test('should reject request with empty string name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Invalid value: name cannot be empty or whitespace only');
  });

  test('should reject request with whitespace-only name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '   ' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Invalid value: name cannot be empty or whitespace only');
  });

  test('should accept valid request with proper name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: 'John Doe' });

    expect(response.status).toBe(201);
    expect(response.body.message).toBe('User created successfully');
    expect(response.body.user.name).toBe('John Doe');
  });

  test('should trim whitespace from valid name', async () => {
    const response = await request(app)
      .post('/users')
      .send({ name: '  Jane Smith  ' });

    expect(response.status).toBe(201);
    expect(response.body.user.name).toBe('Jane Smith');
  });
});

