app.post('/users', (req, res) => {
  // Check if name field is present
  if (req.body.name === undefined) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Missing required field: name'
    });
  }

  // Check if name is a string
  if (typeof req.body.name !== 'string') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Field "name" must be a string'
    });
  }

  // Check if name is empty or whitespace-only
  if (req.body.name.trim() === '') {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Field "name" cannot be empty or whitespace-only'
    });
  }

  // Valid request - process and respond
  const newUser = {
    id: Date.now(), // Simple ID generation
    name: req.body.name,
    email: `${req.body.name.toLowerCase().replace(/\s+/g, '.')}@example.com`,
    createdAt: new Date().toISOString()
  };

  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

