  "description": "Simple user management API with input validation",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "nodemon": "^3.0.1"
  },
  "keywords": ["api", "express", "validation"],
  "author": "",
  "license": "MIT",
  "engines": {
    "node": ">=14.0.0"
  }
}

// Quick test script to verify validation
const http = require('http');

const testCases = [
  {
    name: 'Missing name field',
    data: {},
    expectedError: 'Missing required field: name'
  },
  {
    name: 'Non-string name (number)',
    data: { name: 123 },
    expectedError: 'Invalid data type: name must be a string'
  },
  {
    name: 'Non-string name (boolean)',
    data: { name: true },
    expectedError: 'Invalid data type: name must be a string'
  },
  {
    name: 'Empty string',
    data: { name: '' },
    expectedError: 'Invalid value: name cannot be empty or whitespace only'
  },
  {
    name: 'Whitespace only',
    data: { name: '   ' },
    expectedError: 'Invalid value: name cannot be empty or whitespace only'
  },
  {
    name: 'Valid name',
    data: { name: 'John Doe' },
    expectedStatus: 201
  }
];

console.log('Starting validation tests...\n');

// Start the server in background for testing
const { spawn } = require('child_process');
const serverProcess = spawn('node', ['app.js'], { detached: true });

// Wait for server to start
setTimeout(() => {
  runTests();
}, 2000);

function runTests() {
  let testsCompleted = 0;
  const totalTests = testCases.length;

  testCases.forEach((testCase, index) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/users',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const result = JSON.parse(data || '{}');

        if (testCase.expectedError) {
          if (res.statusCode === 400 && result.error === testCase.expectedError) {
            console.log(`✅ ${testCase.name}: PASS`);
          } else {
            console.log(`❌ ${testCase.name}: FAIL`);
            console.log(`   Expected: 400 with "${testCase.expectedError}"`);
            console.log(`   Got: ${res.statusCode} with "${result.error}"`);
          }
        } else if (testCase.expectedStatus === 201) {
          if (res.statusCode === 201 && result.name === 'John Doe') {
            console.log(`✅ ${testCase.name}: PASS`);
          } else {
            console.log(`❌ ${testCase.name}: FAIL`);
            console.log(`   Expected: 201 with user data`);
            console.log(`   Got: ${res.statusCode}`);
          }
        }

        testsCompleted++;
        if (testsCompleted === totalTests) {
          console.log(`\nTests completed: ${testsCompleted}/${totalTests}`);
          process.kill(-serverProcess.pid);
          process.exit(0);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`❌ ${testCase.name}: FAIL - ${error.message}`);
      testsCompleted++;
    });

    req.write(JSON.stringify(testCase.data));
    req.end();
  });
}

