const express = require('express');
const app = express();

// Production middleware
app.use(express.json());

// Security headers middleware
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'healthy', 
    timestamp: new Date().toISOString(),
    version: '1.0.0'
  });
});

// GET users endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST handler with enhanced input validation
app.post('/users', (req, res) => {
  const { name } = req.body;

  // Input validation: check if name is missing or non-string
  if (name === undefined || name === null) {
    return res.status(400).json({ 
      error: 'Bad Request', 
      message: 'The "name" field is required',
      code: 'VALIDATION_ERROR'
    });
  }

  if (typeof name !== 'string') {
    return res.status(400).json({ 
      error: 'Bad Request', 
      message: 'The "name" field must be a string',
      code: 'VALIDATION_ERROR'
    });
  }

  // Additional validation: trim and check length
  const trimmedName = name.trim();
  if (trimmedName.length === 0) {
    return res.status(400).json({ 
      error: 'Bad Request', 
      message: 'The "name" field cannot be empty',
      code: 'VALIDATION_ERROR'
    });
  }

  if (trimmedName.length > 100) {
    return res.status(400).json({ 
      error: 'Bad Request', 
      message: 'The "name" field must be less than 100 characters',
      code: 'VALIDATION_ERROR'
    });
  }

  // If validation passes, return success response
  res.status(201).json({ 
    message: 'User created successfully', 
    user: { 
      id: Date.now(), // Simple ID generation (would use UUID in production)
      name: trimmedName,
      createdAt: new Date().toISOString()
    } 
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ 
    error: 'Internal Server Error', 
    message: 'An unexpected error occurred',
    requestId: req.id || Date.now().toString(36)
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found', 
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Production configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

const server = app.listen(PORT, HOST, () => {
  console.log(`🚀 Server running on http://${HOST}:${PORT}`);
  console.log(`📊 Health check: http://${HOST}:${PORT}/health`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

module.exports = app;

