#!/usr/bin/env node

const http = require('http');

const options = {
  hostname: 'localhost',
  port: 3000,
  path: '/health',
  method: 'GET',
  timeout: 5000
};

const req = http.request(options, (res) => {
  let data = '';

  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    try {
      const result = JSON.parse(data);
      if (res.statusCode === 200 && result.status === 'ok') {
        console.log('Health check: OK');
        process.exit(0);
      } else {
        console.error('Health check: FAILED - Unexpected response');
        process.exit(1);
      }
    } catch (error) {
      console.error('Health check: FAILED - Invalid JSON response');
      process.exit(1);
    }
  });
});

req.on('error', (error) => {
  console.error('Health check: FAILED - Connection error:', error.message);
  process.exit(1);
});

req.on('timeout', () => {
  console.error('Health check: FAILED - Timeout');
  req.destroy();
  process.exit(1);
});

req.end();

