const express = require('express');
const app = express();

// Middleware to parse JSON request bodies
app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST handler with input validation
app.post('/users', (req, res) => {
  const { name } = req.body;

  // Input validation: check if name is missing or not a string
  if (name === undefined || name === null) {
    return res.status(400).json({ 
      error: 'Name field is required',
      message: 'The name field must be provided in the request body'
    });
  }

  if (typeof name !== 'string') {
    return res.status(400).json({ 
      error: 'Invalid name type',
      message: 'The name field must be a string'
    });
  }

  // Optional: check for empty string
  if (name.trim() === '') {
    return res.status(400).json({ 
      error: 'Invalid name value',
      message: 'The name field cannot be empty'
    });
  }

  // If validation passes, process the request
  // For now, return a success response with the provided name
  const newUser = {
    id: Date.now(), // Simple ID generation
    name: name.trim(),
    email: `${name.toLowerCase().replace(/\s+/g, '.')}@example.com`
  };

  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

